import{_ as e,o as d,c as a,a6 as n}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"连接管理与错误码","description":"连接前言、GOAWAY 的优雅关闭语义、十四个错误码与流错误/连接错误的区分。","frontmatter":{"title":"连接管理与错误码","description":"连接前言、GOAWAY 的优雅关闭语义、十四个错误码与流错误/连接错误的区分。","source":"https://daiw.org/manual/http2-3/h2-connection"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-connection.md","filePath":"manual/computer-programming/http2-3/h2-connection.md"}'),o={name:"manual/computer-programming/http2-3/h2-connection.md"};function s(r,t,c,p,l,i){return d(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="连接管理与错误码" tabindex="-1">连接管理与错误码 <a class="header-anchor" href="#连接管理与错误码" aria-label="Permalink to &quot;连接管理与错误码&quot;">​</a></h1><p>连接前言、GOAWAY 的优雅关闭语义、十四个错误码与流错误/连接错误的区分。</p><h2 id="连接前言" tabindex="-1">连接前言 <a class="header-anchor" href="#连接前言" aria-label="Permalink to &quot;连接前言&quot;">​</a></h2><p>建立 h2 连接后，客户端 <strong>MUST</strong> 首先发送 24 字节的魔数：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PRI * HTTP/2.0\\r\\n\\r\\nSM\\r\\n\\r\\n</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>十六进制：<code>505249202a20485454502f322e300d0a0d0a534d0d0a0d0a</code>。</p><p>设计意图很精巧：这串字节在 1.1 解析器看来是一个<strong>方法为 <code>PRI</code>、目标为 <code>*</code>、版本 <code>HTTP/2.0</code></strong> 的畸形请求，<strong>必定</strong>被 1.1 服务端拒绝——从而防止 h2 客户端误把 h2 帧发给只懂 1.1 的服务端（以及由此产生的协议混淆攻击）。</p><p>前言之后，客户端 <strong>MUST</strong> 立即发一个 <code>SETTINGS</code> 帧（可为空）。服务端也 <strong>MUST</strong> 以 <code>SETTINGS</code> 帧作为其首帧。双方随后互相 <code>ACK</code>。</p><p>服务端收到的首帧不是合法前言 → <strong>MUST</strong> 以 <code>PROTOCOL_ERROR</code> 关闭连接。</p><h2 id="两级错误" tabindex="-1">两级错误 <a class="header-anchor" href="#两级错误" aria-label="Permalink to &quot;两级错误&quot;">​</a></h2><p>这是 h2 相对 1.1 的重要改进：<strong>错误可以只杀一个流，不必杀整条连接</strong>。</p><table tabindex="0"><thead><tr><th></th><th>流错误</th><th>连接错误</th></tr></thead><tbody><tr><td>帧</td><td><code>RST_STREAM</code></td><td><code>GOAWAY</code></td></tr><tr><td>影响</td><td>单个流</td><td>整条连接</td></tr><tr><td>典型场景</td><td>该请求本身有问题（malformed、超限）</td><td>状态失步、帧格式错、HPACK 解码失败</td></tr></tbody></table><p><strong>判定原则</strong>：凡是可能让双方<strong>状态失步</strong>的错误，必须升级为连接错误。最典型的是 <code>COMPRESSION_ERROR</code>——<a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK 动态表</a>一旦失步，后续所有字段块都会解错，只能弃连接。</p><p>1.1 的对照：任何解析错误都只能 <code>400</code> + 关连接，没有中间选项。</p><h2 id="十四个错误码" tabindex="-1">十四个错误码 <a class="header-anchor" href="#十四个错误码" aria-label="Permalink to &quot;十四个错误码&quot;">​</a></h2><p>4 字节无符号整数，<code>RST_STREAM</code> 与 <code>GOAWAY</code> 共用同一套：</p><table tabindex="0"><thead><tr><th>码</th><th>名称</th><th>含义</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><code>NO_ERROR</code></td><td>无错误。用于优雅关闭</td></tr><tr><td><code>0x01</code></td><td><code>PROTOCOL_ERROR</code></td><td>未具体归类的协议违规</td></tr><tr><td><code>0x02</code></td><td><code>INTERNAL_ERROR</code></td><td>实现内部故障</td></tr><tr><td><code>0x03</code></td><td><code>FLOW_CONTROL_ERROR</code></td><td>违反流量控制约定</td></tr><tr><td><code>0x04</code></td><td><code>SETTINGS_TIMEOUT</code></td><td>发出的 SETTINGS 迟迟未被 ACK</td></tr><tr><td><code>0x05</code></td><td><code>STREAM_CLOSED</code></td><td>在已关闭的流上收到帧</td></tr><tr><td><code>0x06</code></td><td><code>FRAME_SIZE_ERROR</code></td><td>帧长度非法</td></tr><tr><td><code>0x07</code></td><td><code>REFUSED_STREAM</code></td><td>流在<strong>任何处理前</strong>被拒绝</td></tr><tr><td><code>0x08</code></td><td><code>CANCEL</code></td><td>不再需要该流（非错误，客户端主动取消）</td></tr><tr><td><code>0x09</code></td><td><code>COMPRESSION_ERROR</code></td><td>HPACK 状态损坏 —— <strong>必为连接错误</strong></td></tr><tr><td><code>0x0a</code></td><td><code>CONNECT_ERROR</code></td><td><code>CONNECT</code> 建立的隧道异常</td></tr><tr><td><code>0x0b</code></td><td><code>ENHANCE_YOUR_CALM</code></td><td>对端行为过载（限流信号）</td></tr><tr><td><code>0x0c</code></td><td><code>INADEQUATE_SECURITY</code></td><td>TLS 配置不满足 h2 要求</td></tr><tr><td><code>0x0d</code></td><td><code>HTTP_1_1_REQUIRED</code></td><td>要求客户端降级到 1.1 重试</td></tr></tbody></table><p>两个值得注意的：</p><ul><li><strong><code>REFUSED_STREAM</code> 保证请求未被处理</strong>——客户端可安全重试<strong>任何</strong>方法，含 <code>POST</code>。这是 1.1 无法提供的确定性（1.1 连接中断时无从判断服务端是否已执行）。</li><li><strong><code>HTTP_1_1_REQUIRED</code></strong> 用于需要 TLS 客户端证书重协商等 h2 禁止的场景（h2 禁止 TLS 重协商）。</li></ul><h2 id="goaway" tabindex="-1">GOAWAY <a class="header-anchor" href="#goaway" aria-label="Permalink to &quot;GOAWAY&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-+-------------------------------------------------------------+</span></span>
<span class="line"><span>|R|                  Last-Stream-ID (31)                        |</span></span>
<span class="line"><span>+-+-------------------------------------------------------------+</span></span>
<span class="line"><span>|                      Error Code (32)                          |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span>|                  Additional Debug Data (*)                    |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>流 ID <strong>MUST</strong> 为 0。核心是 <strong>Last-Stream-ID</strong> 的语义：</p><ul><li>表示发送方<strong>已经或可能已经处理过</strong>的最大流 ID。</li><li><strong>ID 大于该值的流一定未被处理</strong>，客户端可无条件安全重试。</li><li>这使得优雅关闭成为可能，而 1.1 只能靠 <code>Connection: close</code> 且无法告知「哪些请求已处理」。</li></ul><h3 id="优雅关闭的两阶段" tabindex="-1">优雅关闭的两阶段 <a class="header-anchor" href="#优雅关闭的两阶段" aria-label="Permalink to &quot;优雅关闭的两阶段&quot;">​</a></h3><p>生产服务端重启时的标准做法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 发 GOAWAY(Last-Stream-ID = 2^31-1, NO_ERROR)   ← 「我要关了，别开新流」</span></span>
<span class="line"><span>2. 等待 1 个 RTT，让在途请求到达</span></span>
<span class="line"><span>3. 处理完现有流</span></span>
<span class="line"><span>4. 发 GOAWAY(Last-Stream-ID = 实际最大已处理 ID, NO_ERROR)</span></span>
<span class="line"><span>5. 关闭 TCP 连接</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>第一个 <code>GOAWAY</code> 用最大值是关键：它只表达「停止新建」的意图，<strong>不</strong>放弃任何在途请求；第二个才给出真实边界。少了这一步，与客户端刚发出的新流会发生竞态，导致本可成功的请求被误杀。</p><p>发送 <code>GOAWAY</code> 后仍 <strong>MUST</strong> 继续处理 ID ≤ Last-Stream-ID 的流。</p><h2 id="ping-与保活" tabindex="-1">PING 与保活 <a class="header-anchor" href="#ping-与保活" aria-label="Permalink to &quot;PING 与保活&quot;">​</a></h2><ul><li>8 字节不透明载荷，原样回送并置 <code>ACK</code>。</li><li>用途：测 RTT、探活、穿越 NAT 保持映射。</li><li>因为 h2 是单连接长驻，中间设备的空闲超时（常见 60–300 秒）会静默断连，<code>PING</code> 是标准对策。</li></ul><h2 id="connect-在-h2-中的形态" tabindex="-1">CONNECT 在 h2 中的形态 <a class="header-anchor" href="#connect-在-h2-中的形态" aria-label="Permalink to &quot;CONNECT 在 h2 中的形态&quot;">​</a></h2><p><a href="/Front2Full/manual/computer-programming/http11/methods">1.1 的 <code>CONNECT</code></a> 用 authority-form 目标；h2 改为：</p><ul><li><code>:method: CONNECT</code></li><li><strong><code>:authority</code> 必填</strong>，携带 <code>host:port</code></li><li><strong><code>:scheme</code> 与 <code>:path</code> MUST 省略</strong>（省略与否是判定该请求是否为隧道的依据）</li></ul><p>隧道建立后，该<strong>流</strong>上的 <code>DATA</code> 帧载荷即为隧道字节。与 1.1 的关键差异：<strong>隧道只占用一个流，而非整条连接</strong>——同一条 h2 连接可同时承载多个隧道和普通请求。</p><p>扩展 CONNECT（RFC 8441）再加一个 <code>:protocol</code> 伪头，使 WebSocket 能跑在 h2 流上——这补上了 h2 删除 <code>Upgrade</code> 后留下的空缺。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h2-server-push">服务端推送</a>。</p>`,36)])])}const g=e(o,[["render",s]]);export{u as __pageData,g as default};
